import{_ as n,o as s,c as t,a2 as l}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🗺️ 02 · 跨周期价值技术地图","description":"","frontmatter":{},"headers":[],"relativePath":"00-导论与学习哲学/02-跨周期价值技术地图.md","filePath":"00-导论与学习哲学/02-跨周期价值技术地图.md","lastUpdated":1786806808000}'),e={name:"00-导论与学习哲学/02-跨周期价值技术地图.md"};function r(o,a,i,p,d,c){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="🗺️-02-·-跨周期价值技术地图" tabindex="-1">🗺️ 02 · 跨周期价值技术地图 <a class="header-anchor" href="#🗺️-02-·-跨周期价值技术地图" aria-label="Permalink to &quot;🗺️ 02 · 跨周期价值技术地图&quot;">​</a></h1><blockquote><p>一张图告诉你：哪些技术值得你用「年」为单位投入，哪些只是「月」级热点。 本图会随技术演进更新，但<strong>范式层（绿色）几乎不会变</strong>。</p></blockquote><hr><h2 id="一、技术分层模型-从最稳定到最易变" tabindex="-1">一、技术分层模型（从最稳定到最易变） <a class="header-anchor" href="#一、技术分层模型-从最稳定到最易变" aria-label="Permalink to &quot;一、技术分层模型（从最稳定到最易变）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ L0 数学与系统基础（10年+ 不变，是一切的底座）                  │</span></span>
<span class="line"><span>│   线性代数 · 概率统计 · 优化理论 · 信息论 · 分布式系统 · 软件工程 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ L1 AI 核心范式（5年+ 跨周期，建议学透）                        │</span></span>
<span class="line"><span>│   注意力机制 · 反向传播 · 预训练+微调 · 对齐(RLHF/DPO) ·         │</span></span>
<span class="line"><span>│   生成模型范式(Diffusion/AR) · RAG · Agent(规划/记忆/工具)      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ L2 主流架构与训练方法（2-4年，持续演进）                       │</span></span>
<span class="line"><span>│   Transformer变体 · MoE · 长上下文 · LoRA/QLoRA · 量化推理 ·    │</span></span>
<span class="line"><span>│   多模态对齐 · 强化学习(PPO/GRPO)                              │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ L3 具体模型/框架/工具（6-18个月，易过时）                      │</span></span>
<span class="line"><span>│   具体LLM(某版本) · LangChain/LlamaIndex · 某推理引擎 ·         │</span></span>
<span class="line"><span>│   某Agent框架 · 某向量库版本                                   │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ L4 前沿观察区（不确定性高，跟踪不深投）                        │</span></span>
<span class="line"><span>│   世界模型 · 具身智能落地 · AGI路线 · 神经架构搜索新范式 ·       │</span></span>
<span class="line"><span>│   某篇刚出的SOTA论文                                           │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>学习策略</strong>：L0/L1 投入 60% 时间并反复夯实；L2 投入 30%；L3 用到再学；L4 保持阅读、不盲投。</p><hr><h2 id="二、跨周期技术清单-🟢-建议学透" tabindex="-1">二、跨周期技术清单（🟢 建议学透） <a class="header-anchor" href="#二、跨周期技术清单-🟢-建议学透" aria-label="Permalink to &quot;二、跨周期技术清单（🟢 建议学透）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技术</th><th>跨周期理由</th><th>投入建议</th></tr></thead><tbody><tr><td><strong>注意力机制 / Transformer</strong></td><td>已成序列建模事实标准，10 年内难被替代</td><td>学透原理+推导+复杂度</td></tr><tr><td><strong>预训练 + 微调范式</strong></td><td>数据驱动的表示学习范式稳固</td><td>理解 Scaling Law、数据、算力三角</td></tr><tr><td><strong>对齐（RLHF / DPO / 指令微调）</strong></td><td>「让模型符合人类意图」是长期需求</td><td>理解目标函数差异与权衡</td></tr><tr><td><strong>生成模型范式（Diffusion / 自回归）</strong></td><td>两大范式各有适用，思想跨场景</td><td>理解两者本质差异与取舍</td></tr><tr><td><strong>RAG（检索增强）</strong></td><td>解决「知识时效性/可溯源」的刚需</td><td>学透分块/检索/重排/评估</td></tr><tr><td><strong>Agent 范式（规划/记忆/工具）</strong></td><td>比具体框架更持久的能力抽象</td><td>学范式而非某个库</td></tr><tr><td><strong>分布式训练 / 推理优化</strong></td><td>算力约束长期存在</td><td>工程岗必学，算法岗建议了解</td></tr><tr><td><strong>评估方法论</strong></td><td>「不可评估则不可改进」永远成立</td><td>学指标设计、基准、人工评估</td></tr></tbody></table><hr><h2 id="三、稳健工程层-🟡-重点学应用" tabindex="-1">三、稳健工程层（🟡 重点学应用） <a class="header-anchor" href="#三、稳健工程层-🟡-重点学应用" aria-label="Permalink to &quot;三、稳健工程层（🟡 重点学应用）&quot;">​</a></h2><ul><li>向量数据库（Milvus / pgvector / FAISS）的使用与选型</li><li>推理加速（vLLM / TensorRT-LLM / Ollama）的部署与调优</li><li>模型量化（INT8/INT4/AWQ/GPTQ）的精度-速度权衡</li><li>LLMOps：可观测、成本、缓存、降级、评测闭环</li><li>提示工程（CoT / Few-shot / 结构化输出）的系统性方法</li></ul><hr><h2 id="四、前沿观察区-🔵-跟踪不深投" tabindex="-1">四、前沿观察区（🔵 跟踪不深投） <a class="header-anchor" href="#四、前沿观察区-🔵-跟踪不深投" aria-label="Permalink to &quot;四、前沿观察区（🔵 跟踪不深投）&quot;">​</a></h2><blockquote><p>这些方向<strong>重要但结论未定</strong>，建议养成「定期阅读顶会/技术博客」的习惯，而非一次性深度学习。</p></blockquote><ul><li><strong>世界模型（World Model）</strong>：JEPA、Dreamer 路线能否统一感知-预测-控制？</li><li><strong>具身智能（Embodied AI）</strong>：Sim2Real、机器人基础模型的进展</li><li><strong>AGI 路线之争</strong>：尺度定律是否会平缓？推理时计算（test-time compute）是不是新范式？</li><li><strong>Agentic RL</strong>：用强化学习训 Agent 的长期记忆与工具使用</li><li><strong>神经架构新探索</strong>：State Space Model（Mamba）、线性注意力能否替代 softmax 注意力？</li></ul><hr><h2 id="五、谨慎对待区-🔴-了解即可" tabindex="-1">五、谨慎对待区（🔴 了解即可） <a class="header-anchor" href="#五、谨慎对待区-🔴-了解即可" aria-label="Permalink to &quot;五、谨慎对待区（🔴 了解即可）&quot;">​</a></h2><ul><li>把旧技术换皮成「AI + X」但无本质改进的伪创新</li><li>仅靠单篇论文、无复现无落地、benchmark 存疑的「SOTA」</li><li>过度承诺「取代程序员/取代算法工程师」的营销叙事</li></ul><hr><h2 id="六、如何使用这张地图" tabindex="-1">六、如何使用这张地图 <a class="header-anchor" href="#六、如何使用这张地图" aria-label="Permalink to &quot;六、如何使用这张地图&quot;">​</a></h2><ol><li>学任何新技术前，先把它「贴」到上面的某一层。</li><li>贴到 L0/L1 → slowdown，学透；贴到 L3 → 快速上手即可。</li><li>定期（每季度）回看 L4，把其中「升格」到 L2 的技术补学。</li><li>把你的学习产出（项目/笔记）沉淀到 <code>面试真题集</code> 与自己的知识库。</li></ol><blockquote><p>💡 跨周期能力 = <strong>L0/L1 的扎实底座 + 对 L4 的敏锐嗅觉 + 不被 L3 牵着走的自制力。</strong></p></blockquote><hr><p>➡️ 下一步：<a href="./03-学习路线总览">03-学习路线总览</a></p>`,25)])])}const u=n(e,[["render",r]]);export{g as __pageData,u as default};
